package main
import("crypto/sha256";"fmt";"unicode/utf16";"encoding/json";"os";"github.com/johnsonlee/graphite/graphite-server/internal/store")
func main(){if os.Args[1]=="strings"{v,e:=store.LoadStrings(os.Args[2]);r:=map[string]any{};if e!=nil{r["error"]=e.Error()}else{h:=sha256.New();for _,s:=range v{u:=utf16.Encode([]rune(s));n:=len(u);h.Write([]byte{byte(n>>24),byte(n>>16),byte(n>>8),byte(n)});for _,c:=range u{h.Write([]byte{byte(c>>8),byte(c)})}};r["count"]=len(v);r["utf16SHA256"]=fmt.Sprintf("%x",h.Sum(nil))};json.NewEncoder(os.Stdout).Encode(r);return};s,e:=store.OpenMode(os.Args[1],os.Args[2]);r:=map[string]any{};if e!=nil{r["load"]=e.Error()}else{defer s.Close();r["load"]="ok";r["nodes"]=s.NodeCount;r["methods"]=len(s.Metadata.MethodList);n,out,in:=0,0,0;for _,id:=range s.NodeIDs(){_,e:=s.Node(id);if e!=nil{r["nodeError"]=e.Error();break};n++;out+=len(s.Outgoing(id));in+=len(s.Incoming(id))};r["decodedNodes"]=n;r["outgoing"]=out;r["incoming"]=in;r["classOrigins"]=len(s.Metadata.ClassOrigins);entries,e:=s.ResourceList("**");if e!=nil{r["resources"]=e.Error()}else{r["resources"]=len(entries)};v,e:=s.ClassOverview(100);if e!=nil{r["classoverview"]=e.Error()}else if v==nil{r["classoverview"]=nil}else{r["classoverview"]=v.CallSiteCount}};json.NewEncoder(os.Stdout).Encode(r)}
